/** The database surface this runtime needs. PGlite satisfies it. */
export type ReplicaClient = WriterClient & TransactionalLedgerClient;

/**
 * One unit of data from upstream.
 *
 * `mustRefetch` is the server saying the history this cursor points into is
 * gone. It is carried on the revision rather than thrown, because it is a
 * routine control signal, not a failure.
 */
export interface ShapeCheckpoint {
  readonly handle: string;
  readonly offset: string;
}

/** Every shape has an independent opaque position in Electric's log. */
export interface ReplicaCheckpointSet {
  readonly generation: number;
  readonly shapes: Readonly<Record<string, ShapeCheckpoint>>;
}

export interface ReplicaTableRevision {
  readonly shape: string;
  readonly target: TableTarget;
  readonly rows: readonly ChunkRow[];

/** The memory-blocked RA11c browser materializer is available only for qualification runs. */
export function isExperimentalMaterializerEnabled(value: string | undefined): boolean {
  return value === "experimental";
}

/**
 * Explicit real-SDK contract lane. This file is excluded from the default
 * Vitest include and is executed only by vitest.flint-live.config.ts.
 */
import { access } from "node:fs/promises";
import { resolve } from "node:path";
import { pathToFileURL } from "node:url";

import { beforeAll, describe, expect, it, vi } from "vitest";

import { graphStore } from "../graph";
import {
  createFlintLoopbackSpine,
  FLINT_ENTITY_CHANGE_KIND,
  type FlintSpineClientLike,
} from "./__fixtures__/flint-contract";
import {
  createFlintAdapter,
  publishFlintMutation,
  type FlintClientLike,
} from "./flint";
import { RealtimeManager } from "./realtime-manager";

type FlintAdapterConstructor = new (client: unknown) => FlintClientLike;

let RealFlintAdapter: FlintAdapterConstructor;

beforeAll(async () => {
  const root = process.env["FLINT_REALTIME_FABRIC_ROOT"]?.trim();
  if (!root) {
    throw new Error(
      "FLINT_REALTIME_FABRIC_ROOT is required for the explicit Flint live integration lane",
    );
  }

  const entityManagementPath = resolve(
    root,
    "sdks/entity-management/dist/index.js",
  );
  const sdkPath = resolve(root, "sdks/ts/dist/index.js");
  await access(entityManagementPath);
  await access(sdkPath);

  const entityManagement = (await import(
    /* @vite-ignore */ pathToFileURL(entityManagementPath).href
  )) as { RealtimeAdapter?: FlintAdapterConstructor };
  const sdk = (await import(/* @vite-ignore */ pathToFileURL(sdkPath).href)) as {
    EventKind?: { ENTITY_CHANGE?: number };
  };

  if (typeof entityManagement.RealtimeAdapter !== "function") {
    throw new Error(
      `Flint entity-management build does not export RealtimeAdapter: ${entityManagementPath}`,
    );
  }
  if (sdk.EventKind?.ENTITY_CHANGE !== FLINT_ENTITY_CHANGE_KIND) {
    throw new Error(
      `Flint ENTITY_CHANGE kind drifted: expected ${FLINT_ENTITY_CHANGE_KIND}, received ${String(sdk.EventKind?.ENTITY_CHANGE)}`,
    );
  }
  RealFlintAdapter = entityManagement.RealtimeAdapter;
});

describe("explicit Flint RealtimeAdapter live contract", () => {
  it("round-trips the real SDK through the Prometheus normalized graph", async () => {
    graphStore.getState().removeEntity("Order", "live-o1");
    const spine = createFlintLoopbackSpine();
    const flint = new RealFlintAdapter(
      spine as unknown as FlintSpineClientLike,
    );
    const adapter = createFlintAdapter({
      client: flint,
      channelId: "tenant-1",
      consumerId: "live-web-1",
    });
    const manager = new RealtimeManager({ flushInterval: 0, store: graphStore });
    manager.register(adapter, [{ type: "Order" }]);

    try {
      await publishFlintMutation(flint, {
        entityType: "Order",
        entityId: "live-o1",
        tenantId: "tenant-1",
        channelId: "tenant-1",
        data: { id: "live-o1", status: "open" },
        correlationId: "live-correlation-1",
      });

      await vi.waitFor(() => {
        expect(
          graphStore
            .getState()
            .readEntity<Record<string, unknown>>("Order", "live-o1"),
        ).toMatchObject({ id: "live-o1", status: "open" });
      });
    } finally {
      manager.unregisterAll();
      spine.close();
      graphStore.getState().removeEntity("Order", "live-o1");
    }
  });
});

    /// Subscribe to a change stream with per-event RLS re-query filtering.
    ///
    /// For each `ChangeEvent` from the underlying `ChangeStreamSource`, the
    /// changed row is re-queried through the `RestExecutor` under the
    /// subscriber's RLS context. Events that do not survive the re-query
    /// (zero rows returned) are silently dropped. This is non-negotiable:
    /// WAL replication bypasses Postgres RLS, so the re-query is the
    /// authoritative visibility check.
    pub async fn subscribe_rls_filtered(
        &self,
        spec: SubscriptionSpec,
        table_meta: TableMeta,
        who: &RlsContext,
    ) -> Result<BoxStream<'static, Result<ChangeEvent, SubscriptionError>>, SubscriptionError> {
        let stream = self.changes.watch(spec, who).await?;
        let rest = self.rest.clone();
        let who = who.clone();
        Ok(stream
            .filter_map(move |res| {
                let rest = rest.clone();
                let who = who.clone();
                let table_meta = table_meta.clone();
                async move {
                    match res {
                        Ok(event) => match build_pk_filters(&event, &table_meta) {
                            Some(filters) => {
                                let query = RestQuery {
                                    schema: event.schema.clone(),
                                    table: event.table.clone(),
                                    select: None,
                                    filters,
                                    order: None,
                                    limit: Some(1),
                                    offset: None,
                                };
                                match rest.execute(query, &who).await {
                                    Ok(result) => match result.rows {
                                        Json::Array(rows) if !rows.is_empty() => Some(Ok(event)),
                                        _ => None,
                                    },
                                    Err(e) => Some(Err(SubscriptionError::Backend(e))),
                                }
                            }
                            None => None,
                        },
                        Err(e) => Some(Err(SubscriptionError::Stream(e))),
                    }
                }
            })
            .boxed())
    }
}

impl Quarry {
    /// Subscribe to a table's change stream, RLS-filtered, projected to
    /// `async_graphql::Value` objects ready for a `graphql-transport-ws` field.
    ///
    /// This is the seam the gateway's subscription-stream factory calls. Each
    /// surviving `ChangeEvent` becomes an object with the record's columns plus a
    /// synthetic `_op` field naming the operation. Errors from the underlying
    /// RLS-filtered stream are surfaced as GraphQL errors (terminating the field
    /// stream), never silently swallowed.
    ///
    /// SECURITY: `who` carries `keto_subject` (PII) — never logged. Visibility is
    /// enforced by [`Quarry::subscribe_rls_filtered`]'s per-event re-query; this
    /// method only projects events that already survived that check.
    pub async fn subscribe_graphql_values(
        &self,
        spec: SubscriptionSpec,
        table_meta: TableMeta,
        who: &RlsContext,
    ) -> Result<BoxStream<'static, async_graphql::Result<async_graphql::Value>>, SubscriptionError>
    {
        let stream = self.subscribe_rls_filtered(spec, table_meta, who).await?;
        Ok(stream
            .map(|res| match res {
                Ok(event) => Ok(change_event_to_value(&event)),
                Err(e) => Err(async_graphql::Error::new(e.to_string())),
            })
            .boxed())
    }
}

/// Project a `ChangeEvent` into an `async_graphql::Value` object: the record's
/// columns plus a synthetic `_op` field. A delete event with no `record` falls
/// back to `old_record` so subscribers still see the removed row's key columns.
fn change_event_to_value(event: &ChangeEvent) -> async_graphql::Value {
    use async_graphql::{Name, Value};
    use std::collections::BTreeMap;

    let mut map: async_graphql::indexmap::IndexMap<Name, Value> =
        async_graphql::indexmap::IndexMap::new();
    map.insert(Name::new("_op"), Value::from(change_op_str(event.op)));

    let source = event.record.as_ref().or(event.old_record.as_ref());
    if let Some(Json::Object(obj)) = source {
        // Preserve a stable field order for deterministic output.
        let ordered: BTreeMap<&String, &Json> = obj.iter().collect();
        for (k, v) in ordered {
            map.insert(
                Name::new(k),
                Value::from_json(v.clone()).unwrap_or(Value::Null),
            );
        }
    }
    Value::Object(map)
}

/// Stable lowercase operation marker for the synthetic `_op` field.
fn change_op_str(op: fdb_domain::ChangeOp) -> &'static str {
    match op {
        fdb_domain::ChangeOp::Insert => "insert",
        fdb_domain::ChangeOp::Update => "update",
        fdb_domain::ChangeOp::Delete => "delete",
        fdb_domain::ChangeOp::Upsert => "upsert",
        // `ChangeOp` is #[non_exhaustive]; a future variant maps to a neutral marker
        // rather than panicking on a live subscription path.
        _ => "unknown",
    }
}

/// Extract primary-key equality filters from a change event's record.
///
/// Returns `None` when the record is missing, is not a JSON object, or is
/// missing any primary-key column.
fn build_pk_filters(
    event: &ChangeEvent,
    table_meta: &TableMeta,
) -> Option<Vec<(String, String, String)>> {
    let record = event.record.as_ref()?;
    let obj = record.as_object()?;
    table_meta
        .primary_key
        .iter()
        .map(|pk| {
            let value = obj.get(pk).and_then(json_value_to_filter)?;
            Some((pk.clone(), "eq".to_string(), value))
        })

